def slug(text):
    lowered = text.lower()
    # lowercase ASCII letters, keep digits, replace runs of other characters
    # with single hyphens, and strip edge hyphens.
    if not lowered:
        return ""
    parts = [part for part in lowered.split() if part]
    # collapse consecutive hyphens and strip leading/trailing hyphens
    parts = [p for p in parts if p]
    # ensure hyphens only appear between letters; strip edge hyphens.
    result = []
    prev_hyphen = False
    for part in parts:
        if part == "":
            continue
        if part == "-":
            if not prev_hyphen:
                result.append("-")
            prev_hyphen = True
        else:
            result.append(part)
            prev_hyphen = False
    return "".join(result)

